c.python:
class Solution:
    def countSubstrings(self, s: str, c: str) -> int:
        k = s.count(c)
        return k * (k + 1) // 2

c.cpp:
class Solution {
public:
    long long countSubstrings(string s, char c) {
        long long k = count(s.begin(), s.end(), c);
        return k * (k + 1) / 2;
    }
};

c.java:
class Solution {
    public long countSubstrings(String s, char c) {
        long k = 0;
        for (char ch : s.toCharArray()) if (ch == c) k++;
        return k * (k + 1) / 2;
    }
}

c.javascript:
var countSubstrings = function(s, c) {
    let k = 0;
    for (const ch of s) if (ch === c) k++;
    return k * (k + 1) / 2;
};

c.python:
class Solution:
    def countSubstrings(self, s: str, c: str) -> int:
        ans = seen = 0
        for ch in s:
            if ch == c:
                ans += seen + 1
                seen += 1
        return ans

